import { definePluginConfig, type EmitTsExportGroup } from "../../plugin.js";
import { defaultConfig } from "./config.js";
import type { IndexBarrelConfig, IndexBarrelResolvedConfig } from "./types.js";

const HEADER =
  "// AUTO-GENERATED by @ir-kit/kit/sdk/asyncapi — do not hand-edit.";

/**
 * Barrel re-export of every other plugin's output. Runs last (via
 * `dependsOn`) and inspects emitted file paths to decide what to
 * re-export, so the barrel stays correct regardless of which plugins
 * are enabled.
 */
export const indexBarrel = definePluginConfig<
  "index",
  IndexBarrelConfig,
  IndexBarrelResolvedConfig,
  unknown
>({
  name: "index",
  defaultConfig,
  dependsOn: ["typescript", "events", "event-map", "dispatch", "amqplib"],
  handler(plugin) {
    const has = (base: string) =>
      plugin.files.some((f) => f.path === `${base}.gen.ts`);
    const named = (...names: string[]) => names.map((name) => ({ name }));
    const exports: EmitTsExportGroup[] = [];

    if (has("amqp")) {
      exports.push({
        from: "./amqp.gen.js",
        names: named("assertExchanges", "bindAndConsume", "publish"),
      });
    }
    if (has("dispatch")) {
      exports.push({
        from: "./dispatch.gen.js",
        names: named("Registry", "createRegistry"),
      });
    }
    if (has("event-map")) {
      exports.push({
        from: "./event-map.gen.js",
        names: [
          { name: "AnyMessage", isType: true },
          { name: "EventMap", isType: true },
          { name: "isMessageOfType" },
        ],
      });
    }
    if (has("events")) {
      exports.push({
        from: "./events.gen.js",
        names: [{ name: "EventName", isType: true }, { name: "Events" }],
      });
    }
    if (has("handlers")) {
      exports.push({ from: "./handlers.gen.js", names: named("handlers") });
    }
    if (has("types")) {
      exports.push({ from: "./types.gen.js", isType: true });
    }

    plugin.emitTs("index.gen.ts", [], { exports, header: HEADER });
  },
});
